window.products.push({"id":1154281,"name":"National Tree 50 Bulb Outdoor Clear Illuminate Light Set with White Wire-36-Inch Lead Wire with 9-Inch Spacing and 2 Spare Bulb (LS-881-50)","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/814vBqKJHBL._AC_SL1500_.jpg","description":"Ideal for either indoor or outdoor use, this UL listed 50-bulb clear mini-light set has a 36\" lead wire with 9\" spacing between bulbs for a total lighted length of 37 ft. This set features white wire for use on white backgrounds or white trees. If one bulb burns out, the others remain lit. Includes spare bulbs, flasher bulb and replacement fuse. Note that this set does not have an end connect plug.","images":["https://m.media-amazon.com/images/I/814vBqKJHBL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"National Tree Company","source_asin":"B004SICD4G","category_path":"Home & Kitchen"},"sku":"BM-1154281","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B004SICD4G","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B004SICD4G","price_pending":true,"merchant_ready":false});
