window.products.push({"id":1154731,"name":"Winsome Wood Angolo End Table","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/41Jrk+1ZSkL._AC_.jpg","description":"Product Description Angolo End Table with one large drawer and extra shelf for storage. Made of Pinewood with Antique Walnut Finish, Assembly Required Amazon.com A versatile style that works with anything from classic leather furniture to today's global-inspired decors, Winsome Wood's Angolo table collection combines quality solid pine construction with engaging geometry. This end table features a square top perched on four flared legs to form an abbreviated pyramid silhouette. Below, an open shelf adds display space and two large drawers have lots of room for storage. The final effect has an Asian design simplicity enhanced with a rich Antique Walnut finish and nice details such as beveled edges, inset panels, and satin-silver hardware. The table measures 20 inches square by 21 inches high. Assembly is required. --Kara Karll","images":["https://m.media-amazon.com/images/I/41Jrk+1ZSkL._AC_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Winsome","source_asin":"B0012AOGZ2","category_path":"Home & Kitchen"},"sku":"BM-1154731","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B0012AOGZ2","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B0012AOGZ2","price_pending":true,"merchant_ready":false});
